export type CalendarDateValue = Date | string | number | null | undefined;

// Epoch seconds remain below this threshold until November 2286. Using 1e12
// would mistake ordinary pre-2001 millisecond dates for seconds.
const EPOCH_SECONDS_CUTOFF = 10_000_000_000;

/** Parse a calendar value without introducing relative-time or product policy. */
export function parseCalendarDate(value: CalendarDateValue): Date | null {
  if (value == null || value === "") return null;

  if (value instanceof Date) {
    return Number.isNaN(value.getTime()) ? null : value;
  }

  if (typeof value === "number") {
    if (Number.isInteger(value) && value >= 1000 && value <= 9999) {
      return new Date(Date.UTC(value, 0, 1));
    }
    const parsed = new Date(Math.abs(value) < EPOCH_SECONDS_CUTOFF ? value * 1000 : value);
    return Number.isNaN(parsed.getTime()) ? null : parsed;
  }

  const trimmed = value.trim();
  if (!trimmed) return null;
  if (/^\d{4}$/.test(trimmed)) {
    return new Date(Date.UTC(Number(trimmed), 0, 1));
  }
  if (/^\d{4}-\d{2}$/.test(trimmed)) {
    const [year, month] = trimmed.split("-").map(Number);
    if (year && month && month >= 1 && month <= 12) {
      return new Date(Date.UTC(year, month - 1, 1));
    }
  }

  const parsed = new Date(trimmed);
  return Number.isNaN(parsed.getTime()) ? null : parsed;
}

/** Format an absolute career date. This deliberately never says "ago". */
export function formatCalendarDate(
  value: CalendarDateValue,
  locale = "en",
): string | null {
  if (typeof value === "number" && Number.isInteger(value) && value >= 1000 && value <= 9999) {
    return String(value);
  }
  if (typeof value === "string" && /^\d{4}$/.test(value.trim())) {
    return value.trim();
  }

  const parsed = parseCalendarDate(value);
  if (!parsed) return null;
  return new Intl.DateTimeFormat(locale, {
    month: "short",
    year: "numeric",
    timeZone: "UTC",
  }).format(parsed);
}

import { DefinitionItem, DefinitionList } from "@/components/recruit-ui/core/primitives/definition-list";
import { PanelSection } from "@/components/recruit-ui/core/primitives/panel-section";
import { SectionHeader } from "@/components/recruit-ui/core/primitives/section-header";
import { Stack } from "@/components/recruit-ui/core/primitives/stack";
import { Text } from "@/components/recruit-ui/core/primitives/text";
import type { HTMLAttributes, ReactNode } from "react";

export interface CandidateAssessmentFact {
  label: ReactNode;
  value: ReactNode;
}

export interface CandidateAssessmentLabels {
  summary: ReactNode;
  evidence: ReactNode;
  caveats: ReactNode;
  signals: ReactNode;
}

export interface CandidateAssessmentProps
  extends HTMLAttributes<HTMLElement> {
  grade?: ReactNode;
  facts?: readonly CandidateAssessmentFact[];
  summary?: ReactNode;
  evidence?: ReactNode;
  caveats?: ReactNode;
  signals?: ReactNode;
  labels?: Partial<CandidateAssessmentLabels>;
}

const DEFAULT_LABELS: CandidateAssessmentLabels = {
  summary: "Assessment",
  evidence: "Evidence",
  caveats: "Caveats",
  signals: "Signals",
};

function AssessmentSection({
  label,
  children,
}: {
  label: ReactNode;
  children: ReactNode;
}) {
  return (
    <Stack gap="sm">
      <SectionHeader label={label} spacing="none" />
      <Text as="div" variant="muted" size="sm">
        {children}
      </Text>
    </Stack>
  );
}

/** Presentation-only assessment. Hosts own scoring, thresholds, and policy. */
export function CandidateAssessment({
  grade,
  facts = [],
  summary,
  evidence,
  caveats,
  signals,
  labels,
  ...props
}: CandidateAssessmentProps) {
  const resolvedLabels = { ...DEFAULT_LABELS, ...labels };

  return (
    <PanelSection data-slot="candidate-assessment" {...props}>
      <Stack gap="lg">
        {grade}
        {facts.length > 0 ? (
          <DefinitionList>
            {facts.map((fact, index) => (
              <DefinitionItem key={index} label={fact.label}>
                {fact.value}
              </DefinitionItem>
            ))}
          </DefinitionList>
        ) : null}
        {summary != null ? (
          <AssessmentSection label={resolvedLabels.summary}>
            {summary}
          </AssessmentSection>
        ) : null}
        {evidence != null ? (
          <AssessmentSection label={resolvedLabels.evidence}>
            {evidence}
          </AssessmentSection>
        ) : null}
        {caveats != null ? (
          <AssessmentSection label={resolvedLabels.caveats}>
            {caveats}
          </AssessmentSection>
        ) : null}
        {signals != null ? (
          <AssessmentSection label={resolvedLabels.signals}>
            {signals}
          </AssessmentSection>
        ) : null}
      </Stack>
    </PanelSection>
  );
}

import type { MouseEvent } from "react";

const INTERACTIVE_DESCENDANT =
  "button, a, input, select, textarea, [role='button'], [role='link']";

/** Keep nested actions from also selecting their surrounding candidate card. */
export function shouldActivateCandidateCard(
  event: MouseEvent<HTMLElement>,
): boolean {
  if (!(event.target instanceof Element)) return true;
  const nestedControl = event.target.closest(INTERACTIVE_DESCENDANT);
  return nestedControl == null || nestedControl === event.currentTarget;
}

"use client";

import { Button } from "@/components/recruit-ui/core/primitives/button";
import { EmptyState } from "@/components/recruit-ui/core/primitives/empty-state";
import { Heading } from "@/components/recruit-ui/core/primitives/heading";
import { List, ListItem } from "@/components/recruit-ui/core/primitives/list";
import { SectionHeader } from "@/components/recruit-ui/core/primitives/section-header";
import { Separator } from "@/components/recruit-ui/core/primitives/separator";
import { Skeleton } from "@/components/recruit-ui/core/primitives/skeleton";
import { Stack } from "@/components/recruit-ui/core/primitives/stack";
import { Text } from "@/components/recruit-ui/core/primitives/text";
import { useState, type ReactNode } from "react";

import {
  formatCalendarDate,
  type CalendarDateValue,
} from "../core/calendar-date";

export interface CareerHistoryItem {
  title: ReactNode;
  company?: ReactNode;
  /** Host-formatted date text takes precedence over raw dates. */
  dateRange?: ReactNode;
  startDate?: CalendarDateValue;
  endDate?: CalendarDateValue;
  current?: boolean;
  description?: ReactNode;
  /** Stable host grouping key when `company` is not a string. */
  companyGroup?: string;
}

export interface CareerDateRangeProps {
  start?: CalendarDateValue;
  end?: CalendarDateValue;
  current?: boolean;
  presentLabel?: ReactNode;
  locale?: string;
}

/** Absolute calendar dates for a career history; never relative to today. */
export function CareerDateRange({
  start,
  end,
  current = false,
  presentLabel = "Present",
  locale = "en",
}: CareerDateRangeProps) {
  const startLabel = formatCalendarDate(start, locale);
  const endLabel = current ? presentLabel : formatCalendarDate(end, locale);
  if (!startLabel && !endLabel) return null;

  return (
    <>
      {startLabel}
      {startLabel && endLabel ? <span aria-hidden> – </span> : null}
      {endLabel}
    </>
  );
}

interface CareerCompanyGroup {
  key: string | null;
  items: CareerHistoryItem[];
}

function companyGroupKey(item: CareerHistoryItem): string | null {
  if (item.companyGroup?.trim()) return item.companyGroup.trim().toLocaleLowerCase();
  return typeof item.company === "string"
    ? item.company.trim().toLocaleLowerCase() || null
    : null;
}

function groupConsecutiveEmployments(
  items: readonly CareerHistoryItem[],
): CareerCompanyGroup[] {
  return items.reduce<CareerCompanyGroup[]>((groups, item) => {
    const key = companyGroupKey(item);
    const previous = groups.at(-1);

    if (key && previous?.key === key) {
      previous.items.push(item);
    } else {
      groups.push({ key, items: [item] });
    }
    return groups;
  }, []);
}

function descriptionParts(description: string): string[] {
  const parts = description
    .split(/\r?\n|\s+[•●]\s+/)
    .map((part) => part.replace(/^[-–—•●]\s*/, "").trim())
    .filter(Boolean);
  return parts.length > 0 ? parts : [description.trim()];
}

function CareerDescription({ description }: { description: ReactNode }) {
  const [expanded, setExpanded] = useState(false);

  if (typeof description !== "string") {
    return (
      <Text as="div" variant="caption" size="xs" tone="subtle">
        {description}
      </Text>
    );
  }

  const trimmed = description.trim();
  if (!trimmed) return null;
  const parts = descriptionParts(trimmed);
  const hasMore = parts.length > 3 || (parts.length === 1 && trimmed.length > 180);
  const visibleParts = expanded ? parts : parts.slice(0, 3);

  return (
    <Stack gap="xs">
      {parts.length > 1 ? (
        <List
          marker="disc"
          spacing="tight"
          textSize="xs"
          tone="muted"
          className="leading-relaxed"
        >
          {visibleParts.map((part, index) => (
            <ListItem key={index}>{part}</ListItem>
          ))}
        </List>
      ) : (
        <Text
          variant="caption"
          size="xs"
          tone="subtle"
          lineClamp={!expanded && hasMore ? 3 : undefined}
        >
          {trimmed}
        </Text>
      )}
      {hasMore ? (
        <Button
          type="button"
          variant="link-muted"
          size="bare"
          aria-expanded={expanded}
          onClick={() => setExpanded((value) => !value)}
        >
          {expanded ? "Show less" : "Show more"}
        </Button>
      ) : null}
    </Stack>
  );
}

function CareerRole({
  item,
  detailed,
  locale,
  presentLabel,
}: {
  item: CareerHistoryItem;
  detailed: boolean;
  locale: string;
  presentLabel: ReactNode;
}) {
  const date = item.dateRange ?? (
    <CareerDateRange
      start={item.startDate}
      end={item.endDate}
      current={item.current}
      locale={locale}
      presentLabel={presentLabel}
    />
  );
  const hasDate = item.dateRange != null || item.startDate != null || item.endDate != null || item.current;

  return (
    <Stack gap="xs" minWidth="zero">
      <Heading level={5}>{item.title}</Heading>
      {item.company != null || hasDate ? (
        <Text variant="caption" size="xs">
          {item.company}
          {item.company != null && hasDate ? <span aria-hidden> · </span> : null}
          {hasDate ? date : null}
        </Text>
      ) : null}
      {detailed && item.description != null ? (
        <CareerDescription description={item.description} />
      ) : null}
    </Stack>
  );
}

export interface CandidateCareerHistoryTimelineProps {
  items: readonly CareerHistoryItem[];
  loading?: boolean;
  emptyTitle?: string;
  emptyDescription?: string;
  earlierLabel?: ReactNode;
  presentLabel?: ReactNode;
  detailedCompanyGroups?: number;
  locale?: string;
  className?: string;
}

export function CandidateCareerHistoryTimeline({
  items,
  loading = false,
  emptyTitle = "No career history yet",
  emptyDescription = "Career history is not available.",
  earlierLabel = "Earlier",
  presentLabel = "Present",
  detailedCompanyGroups = 2,
  locale = "en",
  className,
}: CandidateCareerHistoryTimelineProps) {
  if (loading && items.length === 0) {
    return (
      <Stack data-slot="candidate-career-history-loading" gap="compact" className={className}>
        <Skeleton preset="row-compact" />
        <Skeleton preset="row-compact" />
      </Stack>
    );
  }

  if (items.length === 0) {
    return (
      <EmptyState
        variant="empty"
        size="inline"
        title={emptyTitle}
        description={emptyDescription}
        className={className}
      />
    );
  }

  const groups = groupConsecutiveEmployments(items);
  const detailedItems = groups
    .slice(0, detailedCompanyGroups)
    .flatMap((group) => group.items);
  const earlierItems = groups
    .slice(detailedCompanyGroups)
    .flatMap((group) => group.items);

  return (
    <Stack data-slot="candidate-career-history" gap="lg" className={className}>
      <Stack gap="lg">
        {detailedItems.map((item, index) => (
          <CareerRole
            key={index}
            item={item}
            detailed
            locale={locale}
            presentLabel={presentLabel}
          />
        ))}
      </Stack>
      {earlierItems.length > 0 ? (
        <Stack gap="md">
          <Separator />
          <SectionHeader label={earlierLabel} spacing="none" />
          <List spacing="normal">
            {earlierItems.map((item, index) => (
              <ListItem key={index}>
                <CareerRole
                  item={item}
                  detailed={false}
                  locale={locale}
                  presentLabel={presentLabel}
                />
              </ListItem>
            ))}
          </List>
        </Stack>
      ) : null}
    </Stack>
  );
}

import { cn } from "@/components/recruit-ui/core/lib/utils";
import { AspectRatio } from "@/components/recruit-ui/core/primitives/aspect-ratio";
import { PanelSection } from "@/components/recruit-ui/core/primitives/panel-section";
import type { HTMLAttributes, ReactNode } from "react";

export interface CandidateCoverImageProps
  extends HTMLAttributes<HTMLDivElement> {
  /** Caller-owned media. The host owns source resolution and alt text. */
  children?: ReactNode;
  softenUntilHover?: boolean;
}

/** A stable 4:1 media frame that performs no fetching or URL resolution. */
export function CandidateCoverImage({
  children,
  softenUntilHover = false,
  className,
  ...props
}: CandidateCoverImageProps) {
  if (children == null) return null;

  return (
    <AspectRatio
      ratio={4}
      data-slot="candidate-cover-image"
      className={cn(
        "w-full overflow-hidden bg-muted [&_img]:h-full [&_img]:w-full [&_img]:object-cover",
        softenUntilHover &&
          "[&_img]:opacity-75 [&_img]:grayscale-[0.2] group-hover:[&_img]:opacity-100 group-hover:[&_img]:grayscale-0",
        className,
      )}
      {...props}
    >
      {children}
    </AspectRatio>
  );
}

export interface CandidateCoverHeaderProps
  extends HTMLAttributes<HTMLDivElement> {
  cover?: ReactNode;
  children: ReactNode;
  padding?: "compact" | "card-header" | "lg";
  softenCoverUntilHover?: boolean;
}

/** One cover-and-identity hierarchy shared by candidate cards and profiles. */
export function CandidateCoverHeader({
  cover,
  children,
  padding = "card-header",
  softenCoverUntilHover = false,
  className,
  ...props
}: CandidateCoverHeaderProps) {
  return (
    <div
      data-slot="candidate-cover-header"
      className={cn("overflow-hidden", className)}
      {...props}
    >
      <CandidateCoverImage softenUntilHover={softenCoverUntilHover}>
        {cover}
      </CandidateCoverImage>
      <PanelSection
        as="div"
        padding={padding === "compact" ? "compact" : "default"}
        className={cn(padding === "card-header" && "pb-3 pt-5")}
      >
        {children}
      </PanelSection>
    </div>
  );
}

"use client";

import {
  DecisionActions,
  type DecisionActionOption,
} from "@/components/recruit-ui/core/primitives/decision-actions";
import type { ReactNode } from "react";

export type CandidateDecisionOption<TValue extends string = string> =
  DecisionActionOption<TValue>;

export interface CandidateDecisionBarProps<TValue extends string = string> {
  options: readonly CandidateDecisionOption<TValue>[];
  value?: TValue;
  onChange: (value: TValue) => void;
  disabled?: boolean;
  ariaLabel?: string;
  trailing?: ReactNode;
  layout?: "inline" | "fill";
}

/** Decision controls only, so the containing card or dialog owns its surface. */
export function CandidateDecisionBar<TValue extends string>({
  options,
  value,
  onChange,
  disabled = false,
  ariaLabel = "Candidate decision",
  trailing,
  layout = "fill",
}: CandidateDecisionBarProps<TValue>) {
  return (
    <DecisionActions
      options={options}
      value={value}
      onChange={onChange}
      disabled={disabled}
      ariaLabel={ariaLabel}
      trailing={trailing}
      layout={layout}
    />
  );
}

"use client";

import {
  ConnectionStatusBar,
  type ConnectionStatusBarAction,
  type ConnectionStatusBarFact,
  type ConnectionStatusBarState,
} from "@/components/recruit-ui/core/primitives/connection-status-bar";
import type { ReactNode } from "react";

type CandidateDestinationActionBase = Omit<
  ConnectionStatusBarAction,
  "ariaLabel" | "iconOnly"
>;

/** Icon-only actions must always supply the accessible name hidden visually. */
export type CandidateDestinationAction =
  | (CandidateDestinationActionBase & {
      iconOnly: true;
      ariaLabel: string;
    })
  | (CandidateDestinationActionBase & {
      iconOnly?: false;
      ariaLabel?: string;
    });
export type CandidateDestinationFact = ConnectionStatusBarFact;
export type CandidateDestinationState = ConnectionStatusBarState;

export interface CandidateDestinationStatusProps {
  state: CandidateDestinationState;
  name: ReactNode;
  description?: ReactNode;
  facts?: readonly CandidateDestinationFact[];
  actions?: readonly CandidateDestinationAction[];
  progress?: number;
  progressLabel?: string;
  details?: ReactNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  className?: string;
}

/** Caller-mapped destination state using the canonical core status surface. */
export function CandidateDestinationStatus({
  state,
  name,
  description,
  facts,
  actions,
  progress,
  progressLabel,
  details,
  open,
  defaultOpen,
  onOpenChange,
  className,
}: CandidateDestinationStatusProps) {
  return (
    <ConnectionStatusBar
      state={state}
      name={name}
      description={description}
      facts={facts}
      actions={actions}
      progress={progress}
      progressLabel={progressLabel}
      open={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
      className={className}
    >
      {details}
    </ConnectionStatusBar>
  );
}

import { Badge } from "@/components/recruit-ui/core/primitives/badge";
import type { HTMLAttributes, ReactNode } from "react";

export type CandidateGrade = "A" | "B" | "C" | "D";

/** Host-owned wording for each display grade. */
export type CandidateGradeLabels = Partial<Record<CandidateGrade, string>>;

/** Visual treatment selected by the host; Recruit UI does not infer grade policy. */
export type CandidateGradeTone =
  | "default"
  | "secondary"
  | "destructive"
  | "outline"
  | "success"
  | "warning"
  | "error"
  | "info"
  | "neutral";

export function normalizeCandidateGrade(
  grade: string | null | undefined,
): CandidateGrade | null {
  const normalized = grade?.trim().toUpperCase();
  return normalized === "A" ||
    normalized === "B" ||
    normalized === "C" ||
    normalized === "D"
    ? normalized
    : null;
}

/** Return presentation only; grade assignment and vocabulary stay host-owned. */
export function candidateGradeLetter(grade: string | null | undefined): string {
  return normalizeCandidateGrade(grade) ?? "—";
}

export function candidateGradeLabel(
  grade: string | null | undefined,
  labels: CandidateGradeLabels,
): string | null {
  const normalized = normalizeCandidateGrade(grade);
  return normalized ? labels[normalized] ?? null : null;
}

export function candidateGradeDisplay(
  grade: string | null | undefined,
  labels: CandidateGradeLabels,
): string {
  const normalized = normalizeCandidateGrade(grade);
  if (!normalized) return "—";
  const label = labels[normalized];
  return label ? `${normalized} — ${label}` : normalized;
}

export interface CandidateGradeBadgeProps
  extends HTMLAttributes<HTMLDivElement> {
  grade: string | null | undefined;
  /** One-off host wording. Takes precedence over `labels`. */
  label?: ReactNode;
  /** Host-owned wording map for shared badge instances. */
  labels?: CandidateGradeLabels;
  /** Host-owned semantic treatment; no meaning is inferred from the letter. */
  tone?: CandidateGradeTone;
  showLabel?: boolean;
}

export function CandidateGradeBadge({
  grade,
  label,
  labels = {},
  tone = "neutral",
  showLabel = true,
  className,
  ...props
}: CandidateGradeBadgeProps) {
  const normalized = normalizeCandidateGrade(grade);
  const resolvedLabel = label === undefined
    ? candidateGradeLabel(normalized, labels)
    : label;

  return (
    <Badge
      data-slot="candidate-grade"
      data-grade={normalized ?? "ungraded"}
      variant={tone}
      className={className}
      {...props}
    >
      <span aria-label={normalized ? `Grade ${normalized}` : "Not graded"}>
        {normalized ?? "—"}
      </span>
      {showLabel && resolvedLabel ? <span>{resolvedLabel}</span> : null}
    </Badge>
  );
}

"use client";

import { FlexItem } from "@/components/recruit-ui/core/primitives/flex-item";
import { Heading } from "@/components/recruit-ui/core/primitives/heading";
import { InteractiveCard } from "@/components/recruit-ui/core/primitives/interactive-card";
import { Stack } from "@/components/recruit-ui/core/primitives/stack";
import { Text } from "@/components/recruit-ui/core/primitives/text";
import { useId, type HTMLAttributes, type MouseEvent, type ReactNode } from "react";

import { shouldActivateCandidateCard } from "./candidate-card-activation";

export interface CandidateInlineCardProps
  extends Omit<HTMLAttributes<HTMLElement>, "onClick" | "title"> {
  name: ReactNode;
  avatar?: ReactNode;
  headline?: ReactNode;
  meta?: ReactNode;
  assessment?: ReactNode;
  status?: ReactNode;
  actions?: ReactNode;
  selected?: boolean;
  subdued?: boolean;
  onSelect?: () => void;
  selectLabel?: string;
}

/** A compact candidate trigger suitable for lists, messages, and previews. */
export function CandidateInlineCard({
  name,
  avatar,
  headline,
  meta,
  assessment,
  status,
  actions,
  selected = false,
  subdued = false,
  onSelect,
  selectLabel = "Open candidate profile",
  "aria-expanded": ariaExpanded,
  className,
  ...props
}: CandidateInlineCardProps) {
  const generatedId = useId();
  const nameId = `${generatedId}-name`;
  const actionId = `${generatedId}-action`;

  return (
    <InteractiveCard
      as="article"
      data-slot="candidate-inline-card"
      selected={selected}
      borderWidth="thin"
      padding="none"
      opacity={subdued ? "subdued" : "full"}
      className={className}
      {...props}
    >
      {onSelect ? (
        <button
          type="button"
          data-slot="candidate-inline-card-trigger"
          aria-label={selectLabel === "Open candidate profile" ? undefined : selectLabel}
          aria-labelledby={selectLabel === "Open candidate profile" ? `${actionId} ${nameId}` : undefined}
          aria-current={selected || undefined}
          aria-expanded={ariaExpanded}
          className="pointer-events-none absolute inset-0 z-10 rounded-[inherit] border-0 bg-transparent p-0 focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
          onClick={onSelect}
        >
          {selectLabel === "Open candidate profile" ? (
            <span id={actionId} className="sr-only">{selectLabel}</span>
          ) : null}
        </button>
      ) : null}
      <div
        data-slot="candidate-inline-card-content"
        className="px-5 py-4"
        onClick={
          onSelect
            ? (event: MouseEvent<HTMLDivElement>) => {
                if (shouldActivateCandidateCard(event)) onSelect();
              }
            : undefined
        }
      >
        <Stack direction="horizontal" gap="compact" align="start">
          {avatar}
          <FlexItem grow minWidth="zero">
            <Stack direction="horizontal" gap="sm" align="center" wrap>
              <Heading id={nameId} level={5} truncate>{name}</Heading>
              {status}
            </Stack>
            {headline != null ? (
              <Text variant="caption" size="sm" truncate marginTop="tight">
                {headline}
              </Text>
            ) : null}
            {meta != null ? (
              <Text variant="caption" size="xs" marginTop="xs">
                {meta}
              </Text>
            ) : null}
            {assessment != null ? (
              <Stack gap="none" marginTop="md">{assessment}</Stack>
            ) : null}
          </FlexItem>
          {actions}
        </Stack>
      </div>
    </InteractiveCard>
  );
}

"use client";

import { Button } from "@/components/recruit-ui/core/primitives/button";
import { Icon } from "@/components/recruit-ui/core/primitives/icon";
import {
  ResponsiveDialog,
  ResponsiveDialogBody,
  ResponsiveDialogClose,
  ResponsiveDialogContent,
  ResponsiveDialogDescription,
  ResponsiveDialogFooter,
  ResponsiveDialogHeader,
  ResponsiveDialogTitle,
  ResponsiveDialogTrigger,
} from "@/components/recruit-ui/core/primitives/responsive-dialog";
import { X } from "lucide-react";
import type { ReactElement, ReactNode } from "react";

export interface CandidateProfileDialogProps {
  accessibleTitle: ReactNode;
  accessibleDescription?: ReactNode;
  trigger?: ReactElement;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  header?: ReactNode;
  children: ReactNode;
  footer?: ReactNode;
  footerLayout?: "auto" | "fill";
  /** Disable only when a composed header or footer supplies its own dialog close. */
  showClose?: boolean;
  closeLabel?: string;
  contentClassName?: string;
  bodyClassName?: string;
}

/** Responsive profile shell with explicit accessibility and composition slots. */
export function CandidateProfileDialog({
  accessibleTitle,
  accessibleDescription,
  trigger,
  open,
  defaultOpen,
  onOpenChange,
  header,
  children,
  footer,
  footerLayout = "auto",
  showClose = true,
  closeLabel = "Close candidate profile",
  contentClassName,
  bodyClassName,
}: CandidateProfileDialogProps) {
  return (
    <ResponsiveDialog
      open={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
    >
      {trigger ? (
        <ResponsiveDialogTrigger asChild>{trigger}</ResponsiveDialogTrigger>
      ) : null}
      <ResponsiveDialogContent
        data-slot="candidate-profile-dialog"
        presentation="preview"
        className={contentClassName}
      >
        {showClose ? (
          <ResponsiveDialogClose asChild>
            <Button
              type="button"
              variant="quiet"
              size="icon"
              aria-label={closeLabel}
              data-slot="candidate-profile-dialog-close"
              className="absolute right-2 top-2 z-10"
            >
              <Icon icon={X} size="lg" />
            </Button>
          </ResponsiveDialogClose>
        ) : null}
        <ResponsiveDialogHeader visibility="screen-reader">
          <ResponsiveDialogTitle>{accessibleTitle}</ResponsiveDialogTitle>
          {accessibleDescription != null ? (
            <ResponsiveDialogDescription>
              {accessibleDescription}
            </ResponsiveDialogDescription>
          ) : null}
        </ResponsiveDialogHeader>
        {header}
        <ResponsiveDialogBody className={bodyClassName}>
          {children}
        </ResponsiveDialogBody>
        {footer != null ? (
          <ResponsiveDialogFooter layout={footerLayout}>
            {footer}
          </ResponsiveDialogFooter>
        ) : null}
      </ResponsiveDialogContent>
    </ResponsiveDialog>
  );
}

